WITH ranked AS (SELECT p.*,rank() OVER(PARTITION BY p.id_level ORDER BY p.time)::integer AS position FROM zc_private.zsl_provisional_level_result p JOIN public.zsl_level l ON l.id=p.id_level WHERE l.id_round=$1 AND p.finalised) INSERT INTO public.zsl_level_result(id_level,id_user,time,position,points,date_created) SELECT r.id_level,r.id_user,r.time::real,r.position,coalesce(ps.points[r.position],ps.minimum_points),clock_timestamp() FROM ranked r JOIN public.zsl_round event ON event.id=$1 JOIN public.zsl_season s ON s.id=event.id_season JOIN public.zsl_points_structure ps ON ps.id=s.id_points_structure ON CONFLICT(id_level,id_user) DO UPDATE SET time=excluded.time,position=excluded.position,points=excluded.points,date_updated=clock_timestamp()
